from pathlib import Path
import json,sys,time

campaign=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
model_task="A2Z-V4-SOL-BUILD-20261007-R4"
req=campaign/"requests"/f"{model_task}.json"
mr=campaign/"model_results"/f"{model_task}.json"
runs=campaign/"models/runs"

if mr.exists():
    print("E120=R4_RESULT_EXISTS",flush=True)
    raise SystemExit(0)

matches=[]
if runs.exists():
    for taskp in runs.rglob("TASK.json"):
        try:
            task=json.loads(taskp.read_text())
        except Exception:
            continue
        if task.get("task_id")==model_task:
            cp=taskp.parent
            item={"checkpoint":str(cp)}
            for name in ("WORKER.json","COMPLETE.json","events.jsonl"):
                p=cp/name
                item[name]=p.exists()
                if p.exists():
                    try:
                        item[name+"_mtime"]=p.stat().st_mtime
                    except Exception:
                        pass
            wp=cp/"WORKER.json"
            if wp.exists():
                try:
                    w=json.loads(wp.read_text())
                    item["worker_model"]=w.get("model")
                    item["worker_state"]=w.get("state")
                    item["worker_started_at"]=w.get("started_at")
                except Exception as e:
                    item["worker_error"]=type(e).__name__+":"+str(e)
            cpj=cp/"COMPLETE.json"
            if cpj.exists():
                try:
                    c=json.loads(cpj.read_text())
                    item["complete_task_id"]=c.get("task_id")
                    item["complete_timestamp"]=c.get("timestamp")
                    item["complete_has_final"]=bool(c.get("final"))
                except Exception as e:
                    item["complete_error"]=type(e).__name__+":"+str(e)
            ep=cp/"events.jsonl"
            if ep.exists():
                try:
                    lines=[x for x in ep.read_text(errors="replace").splitlines() if x.strip()]
                    item["event_count"]=len(lines)
                    item["last_event"]=lines[-1][:500] if lines else ""
                except Exception as e:
                    item["events_error"]=type(e).__name__+":"+str(e)
            matches.append(item)

out={
 "request_exists":req.exists(),
 "result_exists":mr.exists(),
 "matching_runs":matches,
}
print("E120_STATUS "+json.dumps(out,separators=(",",":"),default=str),flush=True)

if not req.exists():
    print("E120=REQUEST_MISSING",flush=True); raise SystemExit(31)
if not matches:
    print("E120=REQUEST_NOT_PICKED_UP",flush=True); raise SystemExit(20)
latest=sorted(matches,key=lambda x:x.get("worker_started_at") or 0)[-1]
if latest.get("COMPLETE.json"):
    if latest.get("complete_has_final"):
        print("E120=COMPLETE_PRESENT_RESULT_ENVELOPE_MISSING",flush=True); raise SystemExit(21)
    print("E120=COMPLETE_PRESENT_FINAL_MISSING",flush=True); raise SystemExit(22)
if latest.get("WORKER.json"):
    print("E120=RUN_STARTED_INCOMPLETE",flush=True); raise SystemExit(23)
print("E120=RUN_DIR_INCOMPLETE",flush=True); raise SystemExit(24)
